const Portal={init:function(){"undefined"!=typeof firebase&&firebase.auth&&firebase.auth().onAuthStateChanged(t=>{const o=document.querySelectorAll(".portal-link");t?(console.log("[STEMulus] User signed in:",t.email),o.forEach(t=>{t.textContent="Go to Portal",t.href="portal-dashboard.html"})):(console.log("[STEMulus] User signed out."),o.forEach(t=>{t.textContent="Parent Portal",t.href="parent-login.html"}))})},login:async function(t,o){try{await firebase.auth().signInWithEmailAndPassword(t,o),window.location.href="portal-dashboard.html"}catch(t){throw t}},logout:async function(){try{await firebase.auth().signOut(),window.location.href="index.html"}catch(t){console.error("Logout Error:",t)}}};document.addEventListener("DOMContentLoaded",Portal.init);